{"source": "def investigate(context, acquire):
    hist = acquire("history")

    def simulate(actions, put_mode, trig, chan):
        committed = {}
        tx = {"main": None, "other": None}

        def view(conn):
            if tx[conn] is None:
                return committed
            d = dict(committed)
            for k, v in tx[conn].items():
                if v is None:
                    d.pop(k, None)
                else:
                    d[k] = v
            return d

        changes = 0
        total_main = 0
        total_other = 0

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                if tx[conn] is None:
                    tx[conn] = {}
            elif op == "commit":
                if tx[conn] is not None:
                    for k, v in tx[conn].items():
                        if v is None:
                            committed.pop(k, None)
                        else:
                            committed[k] = v
                    tx[conn] = None
            elif op == "rollback":
                tx[conn] = None
            elif op == "put":
                k = act["key"]
                v = act["value"]
                cur = view(conn)
                existed = k in cur
                if existed:
                    if put_mode == "ignore":
                        pass
                    else:
                        if tx[conn] is None:
                            committed[k] = v
                        else:
                            tx[conn][k] = v
                        changes = 1
                        if conn == "main":
                            total_main += 1
                        else:
                            total_other += 1
                else:
                    if tx[conn] is None:
                        committed[k] = v
                    else:
                        tx[conn][k] = v
                    changes = 1
                    if conn == "main":
                        total_main += 1
                    else:
                        total_other += 1
            elif op == "update":
                k = act["key"]
                v = act["value"]
                cur = view(conn)
                if k in cur:
                    if tx[conn] is None:
                        committed[k] = v
                    else:
                        tx[conn][k] = v
                    changes = 1
                    if conn == "main":
                        total_main += 1
                    else:
                        total_other += 1
            elif op == "delete":
                k = act["key"]
                cur = view(conn)
                if k in cur:
                    if tx[conn] is None:
                        committed.pop(k, None)
                    else:
                        tx[conn][k] = None
                    changes = 1
                    if conn == "main":
                        total_main += 1
                    else:
                        total_other += 1

        if chan == "changes":
            ch = changes
        elif chan == "total_changes":
            ch = total_main
        else:
            ch = total_main + total_other
        return ch, len(committed), sum(committed.values())

    put_modes = ["ignore", "replace", "upsert"]
    trigs = [False, True]
    chans = ["changes", "total_changes", "total_changes_both"]

    consistent = []
    for pm in put_modes:
        for tg in trigs:
            for ch in chans:
                ok = True
                for rec in hist:
                    acts = rec.get("actions", [])
                    obs = rec.get("observed", {})
                    c, cc, cs = simulate(acts, pm, tg, ch)
                    if c != obs.get("channel") or cc != obs.get("committed_count") or cs != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    consistent.append((pm, tg, ch))

    if not consistent:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = set()
    for pm, tg, ch in consistent:
        c, cc, cs = simulate(actions, pm, tg, ch)
        if goal == "channel":
            vals.add(c)
        elif goal == "committed_count":
            vals.add(cc)
        elif goal == "committed_sum":
            vals.add(cs)
        else:
            return {"value": None, "unresolved": True}
    if len(vals) == 1:
        return {"value": list(vals)[0], "unresolved": False}
    return {"value": None, "unresolved": True}
", "scope": "Simulates the disclosed 18-member SQLite family (put mode x trigger x channel) and answers only when all candidates consistent with calibration agree.", "lesson": "Enumerate family members, filter by calibration receipts, and predict only when the surviving set is unanimous; otherwise report unresolved."}
